const execution = $json.execution || {};
const failedWorkflow = $json.workflow || {};
const error = execution.error || ($json.trigger && $json.trigger.error) || {};
return {
  json: {
    workflow_id: failedWorkflow.id || null,
    workflow_name: failedWorkflow.name || null,
    execution_id: execution.id ? String(execution.id) : null,
    execution_url: execution.url || null,
    mode: execution.mode || 'trigger',
    last_node: execution.lastNodeExecuted || (error.node && error.node.name) || null,
    error_message: String(error.message || 'Unknown error').slice(0, 1000),
    error_detail: String(error.description || error.stack || '').slice(0, 2000)
  }
};
